func (h *handler) regenerateAPIKeyHandler(w http.ResponseWriter, r *http.Request) {
	userID := request.UserID(r)
	apiKeyID := request.RouteInt64Param(r, "apiKeyID")
	if apiKeyID == 0 {
		response.JSONBadRequest(w, r, errors.New("invalid API key ID"))
		return
	}

	apiKey, err := h.store.RegenerateAPIKey(userID, apiKeyID)
	if err != nil {
		if errors.Is(err, storage.ErrAPIKeyNotFound) {
			response.JSONNotFound(w, r)
			return
		}
		response.JSONServerError(w, r, err)
		return
	}

	response.JSON(w, r, apiKey)
}

